export const GROWTH_WORDS: Readonly<Record<Lang, GrowthWords>> = { en, tr, de, es, fr };

export function fill(t: string, vars: Record<string, string | number>): string {
  return t.replace(/\{(\w+)\}/g, (_, k: string) => (vars[k] !== undefined ? String(vars[k]) : `{${k}}`));
}

